const USER=process.env.WP_USER.trim(),PASS=process.env.WP_APP_PASS.trim();
const AUTH='Basic '+Buffer.from(USER+':'+PASS).toString('base64');
const BASE='https://dev.avesa.lt/wp-json/code-snippets/v1/snippets';
const TOK=process.env.GH_TOKEN;
process.env.NODE_TLS_REJECT_UNAUTHORIZED='0';
const D='', A='';
async function putResult(n,o){
  const url='https://api.github.com/repos/raimis079-creator/petshop-bridge/contents/screenshots/'+n;
  let sha;const g=await fetch(url,{headers:{Authorization:'Bearer '+TOK}});
  if(g.status===200) sha=(await g.json()).sha;
  const b={message:'r '+n,content:Buffer.from(JSON.stringify(o,null,1)).toString('base64')}; if(sha)b.sha=sha;
  const r=await fetch(url,{method:'PUT',headers:{Authorization:'Bearer '+TOK,'Content-Type':'application/json'},body:JSON.stringify(b)});
  console.log('putResult',n,r.status);
}
async function putFile(p,buf,m){
  const url='https://api.github.com/repos/raimis079-creator/petshop-bridge/contents/'+p;
  let sha;const g=await fetch(url,{headers:{Authorization:'Bearer '+TOK}});
  if(g.status===200) sha=(await g.json()).sha;
  const b={message:m,content:buf.toString('base64')}; if(sha)b.sha=sha;
  const r=await fetch(url,{method:'PUT',headers:{Authorization:'Bearer '+TOK,'Content-Type':'application/json'},body:JSON.stringify(b)});
  console.log('putFile',p,r.status);
}
async function snip(name,code){
  const r=await fetch(BASE,{method:'POST',headers:{Authorization:AUTH,'Content-Type':'application/json'},
    body:JSON.stringify({name,code:Buffer.from(code,'base64').toString('utf8'),scope:'global',active:true,priority:11})});
  return (await r.json()).id;
}
const out={version:'S711-V1',errors:[]};
try{
  const idD=await snip('TEMP Katalogo Diegejas v20 (S711)', D);
  await new Promise(x=>setTimeout(x,3000));
  const t=await (await fetch('https://dev.avesa.lt/?ps_kat_deploy=D711x&k=ps2026&cb='+Date.now(),{headers:{'User-Agent':'Mozilla/5.0'}})).text();
  try{out.deploy=JSON.parse(t);}catch(e){out.deploy_raw=t.slice(0,700);}
  await fetch(BASE+'/'+idD,{method:'POST',headers:{Authorization:AUTH,'Content-Type':'application/json'},body:JSON.stringify({active:false})});
}catch(e){out.errors.push({s:'deploy',e:String(e)});}
let ck=null,idA=null;
try{
  idA=await snip('TEMP Auth Cookie (S711)', A);
  await new Promise(x=>setTimeout(x,3000));
  ck=JSON.parse(await (await fetch('https://dev.avesa.lt/?ps_auth649=A649x&k=ps2026&cb='+Date.now(),{headers:{'User-Agent':'Mozilla/5.0'}})).text());
}catch(e){out.errors.push({s:'auth',e:String(e)});}
if(ck&&ck.auth_ck){
 try{
  const {chromium}=await import('playwright');
  const br=await chromium.launch();
  const ctx=await br.newContext({viewport:{width:1560,height:1000},ignoreHTTPSErrors:true});
  await ctx.addCookies([
    {name:ck.log_vardas,value:ck.log_ck,domain:'dev.avesa.lt',path:'/',httpOnly:true,secure:true},
    {name:ck.auth_vardas,value:ck.auth_ck,domain:'dev.avesa.lt',path:'/',httpOnly:true,secure:true},
    {name:ck.auth_vardas,value:ck.auth_ck,domain:'dev.avesa.lt',path:'/wp-admin',httpOnly:true,secure:true}]);
  const pg=await ctx.newPage();
  const errs=[]; pg.on('pageerror',e=>errs.push(String(e)));
  pg.on('dialog',d=>d.accept());
  // ZZ TEST prekes — saugios
  await pg.goto('https://dev.avesa.lt/wp-admin/admin.php?page=ps-katalogas&atnaujinti=1&q=ZZ+TEST&kruva=visos&per=20',{waitUntil:'domcontentloaded',timeout:150000});
  await pg.waitForTimeout(2500);
  out.pradzia=await pg.evaluate(()=>({
    eiluciu:document.querySelectorAll('.pskat-t tbody tr[data-id]').length,
    varneliu:document.querySelectorAll('input.ps-zym').length,
    juosta_pasleps:document.getElementById('pskat-masine').hidden}));
  if(out.pradzia.varneliu>0){
    await pg.click('input.ps-zym'); await pg.waitForTimeout(500);
    out.po_zymejimo=await pg.evaluate(()=>({
      kiek:(document.getElementById('ms-kiek')||{}).textContent,
      juosta:!document.getElementById('pskat-masine').hidden,
      eilute_zym:document.querySelectorAll('.pskat-t tbody tr.zym').length}));
    await putFile('screenshots/s711_zymejimas.png', await pg.screenshot(), 'S711 zymejimas');
    // PERZIURA
    await pg.selectOption('#ms-veiksmas','draft');
    await pg.click('#ms-perziura'); await pg.waitForTimeout(3000);
    out.perziura=await pg.evaluate(()=>{
      const l=document.getElementById('ps-langas');
      return {matomas:!l.hidden,
        antraste:(document.getElementById('lg-antraste')||{}).textContent,
        santrauka:(document.getElementById('lg-santrauka')||{}).textContent.trim().replace(/\s+/g,' '),
        eiluciu:l.querySelectorAll('.lg-t tr').length-1,
        persp:l.querySelectorAll('.lg-t tr.persp-eil').length};
    });
    await putFile('screenshots/s711_perziura.png', await pg.screenshot(), 'S711 perziura');
    // VYKDOM
    await pg.click('#lg-vykdyk'); await pg.waitForTimeout(4000);
    out.po_vykdymo=await pg.evaluate(()=>{
      const p=document.querySelector('.pskat-pranes');
      return {pranesimas:p?p.textContent.trim().replace(/\s+/g,' ').slice(0,140):null,
        langas_uzdarytas:document.getElementById('ps-langas').hidden,
        pazymeta:document.querySelectorAll('input.ps-zym:checked').length};
    });
    await putFile('screenshots/s711_atlikta.png', await pg.screenshot(), 'S711 atlikta');
    // GRAZINAM
    const gr=await pg.$('.pskat-pranes button');
    if(gr){ await gr.click(); await pg.waitForTimeout(4000);
      out.po_grazinimo=await pg.evaluate(()=>document.querySelectorAll('.pskat-t tbody tr[data-id]').length); }
  }
  out.js=errs;
  await br.close();
 }catch(e){out.errors.push({s:'ui',e:String(e)});}
}
if(idA) await fetch(BASE+'/'+idA,{method:'POST',headers:{Authorization:AUTH,'Content-Type':'application/json'},body:JSON.stringify({active:false})});
try{
  const r=await fetch('https://dev.avesa.lt/parduotuve/?cb='+Date.now(),{headers:{'User-Agent':'Mozilla/5.0'}});
  const t=await r.text(); out.sveikata={http:r.status,len:t.length,fatal:/Fatal error/i.test(t)};
}catch(e){}
await putResult('s711_v1.json',out);
console.log('DONE');
